    Hypothesis ABOVE : above_sp MI A sp ds 392.
    Hypothesis BUD : len + 24 <= DS_MAXLEN.
    Hypothesis ROOM : ds_room SEGS Ly.L MI A.
    Hypothesis POST : forall A' R' M' model' B' (J : Z -> Prop),
