    Record atdp (R1 : bvmap 5 word) (M1 : mem) (v : Z) : Prop := ATDP {
      ad_st : stores_in (fun a => zwin (sp - 144) sp a \/ zwin (ds + 256) (ds + 260) a) M M1;
      ad_fill : fld SEGS M1 (ds + 256) 4 32;
      ad_sv : slots SEGS M1 sp SVOP;
      ad_r1 : getr R1 1%bv = Z_to_bv 64 OP_RET; ad_r2 : getr R1 2%bv = Z_to_bv 64 (sp - 96);
      ad_r3 : getr R1 3%bv = getr R 3%bv; ad_r4 : getr R1 4%bv = getr R 4%bv;
      ad_r8 : getr R1 8%bv = Z_to_bv 64 ds; ad_r11 : getr R1 11%bv = Z_to_bv 64 (ds + 8); ad_r12 : getr R1 12%bv = Z_to_bv 64 (ds + 112);
      ad_r13 : getr R1 13%bv = Z_to_bv 64 32; ad_r14 : getr R1 14%bv = Z_to_bv 64 v; ad_v : 0 <= v < 2 ^ 64;
      ad_cs : forall r, In r [23; 24; 25; 26; 27]%bv -> getr R1 r = getr R r }.

