    Ltac fin_first HR1 M1 v Hv cl :=
      apply (stage2 _ M1 v); constructor;
      [ cl; subst M1; stores_tower
      | let FB := fresh in cl;
        pose proof (fld4_of_bytes M1 (ds + 256) 32 0 0 0 32 ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia)) as FB;
        replace (32 + 256 * 0 + 65536 * 0 + 16777216 * 0) with 32 in FB by lia;
        apply FB; [ | | | | vm_compute; reflexivity];
          unfold fld; subst M1; peel;
          lazymatch goal with |- rdn _ (wbytes _ (Z_to_bv 64 ?b) _) (Z_to_bv 64 ?a) _ = _ => replace (Z_to_bv 64 a) with (Z_to_bv 64 b) by (f_equal; lia) end;
          apply ContLib.rdn_wbytes_hit1; rewrite u64_of_Z by lia; lia
      | cl; subst M1; unfold SVOP; slots_tower
      | let V := fresh in regval HR1 (1%bv : reg) OP_RET V; exact V
      | let V := fresh in regval HR1 (2%bv : reg) (sp - 96) V; exact V
      | kept_chain HR1 | kept_chain HR1
      | let V := fresh in regval HR1 (8%bv : reg) ds V; exact V
      | let V := fresh in regval HR1 (11%bv : reg) (ds + 8) V; exact V
      | let V := fresh in regval HR1 (12%bv : reg) (ds + 112) V; exact V
      | let V := fresh in regval HR1 (13%bv : reg) 32 V; exact V
      | let X := fresh in rreg HR1 (14%bv : reg) X; rewrite X; evs; regsub; first [reflexivity | apply zext32_mod; lia]
      | exact Hv
      | let r := fresh "r" in let Hr := fresh "Hr" in intros r Hr; cbn in Hr; repeat (destruct Hr as [<-|Hr]; [kept_chain HR1|]); destruct Hr ].
    Ltac fin_cached HR1 M1 v Hv Hf Ifill STM cl :=
      apply (stage2 _ M1 v); constructor;
      [ cl; subst M1; stores_tower
      | rewrite <- Hf; replace (ds + 256) with (ds + 112 + 144) by lia; eapply fld_agree; [lia | cbn; lia | exact Ifill |];
        lazymatch goal with |- agree_on _ _ ?mm => let STx := fresh in assert (STx : stores_in (zwin (sp - 144) sp) STM mm) by (cl; subst M1; stores_tower);
          eapply stores_in_agree; [exact STx|] end; let a := fresh "a" in let Ha := fresh "Ha" in intros a Ha; unfold zwin in *; cbn in Ha; lia
      | cl; subst M1; unfold SVOP; slots_tower
      | let V := fresh in regval HR1 (1%bv : reg) OP_RET V; exact V
      | let V := fresh in regval HR1 (2%bv : reg) (sp - 96) V; exact V
      | kept_chain HR1 | kept_chain HR1
      | let V := fresh in regval HR1 (8%bv : reg) ds V; exact V
      | let V := fresh in regval HR1 (11%bv : reg) (ds + 8) V; exact V
      | let V := fresh in regval HR1 (12%bv : reg) (ds + 112) V; exact V
      | let V := fresh in regval HR1 (13%bv : reg) 32 V; exact V
      | let X := fresh in rreg HR1 (14%bv : reg) X; rewrite X; evs; regsub; first [reflexivity | apply zext32_mod; lia]
      | exact Hv
      | let r := fresh "r" in let Hr := fresh "Hr" in intros r Hr; cbn in Hr; repeat (destruct Hr as [<-|Hr]; [kept_chain HR1|]); destruct Hr ].

